    Call: 'function call', Bin: 'operator', Unary: 'operator', Bool: 'operator',
    Compare: 'comparison', IfExp: 'conditional expression', Lambda: 'lambda',
    Comp: 'comprehension', Dict: 'literal', Set: 'literal',
